import json,subprocess,time,urllib.request
runid='run_mvaxg8be_1099f77b3b'
observations=[]
for i in range(3):
 try:
  with urllib.request.urlopen('http://127.0.0.1:8787/v1/status/'+runid,timeout=6) as q:v=json.load(q)
  d=v.get('durable') or {}
  c=d.get('workflow_cursor') or {}
  observations.append({'step':i+1,'state':v.get('state'),'job_status':d.get('job_status'),'generation':d.get('generation'),'workflow':c.get('step_id'),'phase':c.get('step_phase'),'active_execution':bool(c.get('active_role_execution_id'))})
  if d.get('job_status') in ('BLOCKED','DONE','FAILED','CANCELLED'):break
 except Exception as e:observations.append({'step':i+1,'error':type(e).__name__})
 if i<2: time.sleep(8)
body='DEBUGAI_REAL_E2E_PROGRESS_WINDOW\n'+json.dumps({'run_id':runid,'observations':observations},ensure_ascii=False,indent=2)
p=subprocess.run(['gh','api','-X','POST','repos/seigo-gace/debug-ai/issues/41/comments','-f','body='+body],capture_output=True,text=True,timeout=28)
if p.returncode:raise SystemExit('PROGRESS_POST_FAILED')
print('E2E_PROGRESS_COMMENT='+json.loads(p.stdout)['html_url'])
PY
